  },
  formData: {
    item_template_reference: '{"item_id":54,"type":"attachment","payload":{"attachment":"string","image_id":0,"form_id":0,"folder_id":0,"file_version_id":0,"drawing_revision_id":0,"document_management_document_revision_id":0}}'
  }
};

request(options, function (error, response, body) {
